# Global counters to track exploitation and generosity history
_exploitation_count = 0
_total_donations_by_agent = 0
_rounds_since_last_exploit = 0

def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Asymmetric reputation update: punish defection more than reward donation
    # Also, rely less on reputation over time (shrink step size)
    base_step = 0.15
    # Reduce step as rounds increase to stabilize reputation
    decay = max(0.5, 1.0 - round_num / 500)  # gradually shrink to 0.5
    step = base_step * decay

    if observation['action'] == 'donate':
        new_rep = current_reputation + step
    else:
        # Punish defection more severely (larger step down)
        new_rep = current_reputation - step * 1.5  # 1.5x punishment

    # Keep within bounds
    return max(-1.0, min(1.0, new_rep))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    global _exploitation_count, _total_donations_by_agent, _rounds_since_last_exploit

    # Process new history entries since last call
    # (assumes sequential rounds – each call processes exactly one new entry)
    if len(my_history) > _total_donations_by_agent:
        for entry in my_history[_total_donations_by_agent:]:
            if entry['action'] == 'donate':
                _total_donations_by_agent += 1
                if entry['partner_action'] != 'donate':
                    _exploitation_count += 1
                    _rounds_since_last_exploit = 0
                else:
                    _rounds_since_last_exploit += 1
            else:
                # If we didn't donate, we don't count that as an exploitation risk
                _rounds_since_last_exploit += 1

    # Decision logic:
    # - Never donate to very low reputation agents
    if recipient_reputation < -0.6:
        return False

    # - If we have been exploited many times relative to donations, become very cautious
    if _total_donations_by_agent > 0:
        exploitation_rate = _exploitation_count / _total_donations_by_agent
        # Tighten threshold if exploitation rate exceeds 40%
        if exploitation_rate > 0.4:
            # In addition, if we haven't been exploited recently, we can be slightly more trusting
            if _rounds_since_last_exploit > 10:
                return recipient_reputation > 0.4
            else:
                return recipient_reputation > 0.7
        else:
            # Moderate threshold, but become stricter in later rounds
            if round_num > 200:
                return recipient_reputation > 0.4
            else:
                return recipient_reputation > 0.2
    else:
        # Early game: moderate threshold, but become more careful if many rounds passed without action
        if round_num > 50:
            return recipient_reputation > 0.3
        else:
            return recipient_reputation > 0.0

