    for entry in recent_window:
        if entry['action'] == 'donate':
            recent_donations += 1
            if entry['partner_action'] != 'donate':
                recent_exploited += 1
    exploitation_rate = recent_exploited / recent_donations if recent_donations > 0 else 0.0

    # Base threshold: slower increase over rounds, with exploitation cap
    base_threshold = 0.1 * (round_num / 50)   # 0.1 at round 50, 0.2 at round 100, ...
    if exploitation_rate > 0.6:
