            else:
                # No donation: reset both streaks
                _consecutive_donations = 0
                _consecutive_exploited = 0
        _last_round_processed = len(my_history)

    # Recent statistics over a smaller window (10 rounds)
    window = 10
    recent = my_history[-window:] if len(my_history) >= window else my_history
    recent_len = len(recent)
    if recent_len == 0:
        our_donation_rate = 0.5
        partner_donation_rate = 0.5
    else:
        our_donations = sum(1 for e in recent if e['action'] == 'donate')
        partner_donations = sum(1 for e in recent if e['partner_action'] == 'donate')
        our_donation_rate = our_donations / recent_len
        partner_donation_rate = partner_donations / recent_len

    # Dynamic threshold with gentle round progression
    threshold = 0.2 + 0.04 * (round_num / 100)

    # Adjust based on recent mutual cooperation
    if our_donation_rate > 0.7 and partner_donation_rate > 0.6:
        threshold -= 0.2       # become more generous
    elif our_donation_rate < 0.3 and partner_donation_rate < 0.4:
        threshold += 0.2       # become more strict

    # Respond to abuse streaks
    if _consecutive_exploited >= 2:
        threshold += 0.3
    # Reward own consistent good behaviour
    if _consecutive_donations >= 4 and partner_donation_rate > 0.7:
        threshold -= 0.1

    # Overrides for extreme reputations
