            if entry['action'] == 'donate':
                _own_donation_count += 1
                if entry['partner_action'] != 'donate':
                    _own_exploitation_count += 1
        _last_round_processed = len(my_history)

    # Compute overall exploitation ratio (only if we have donated)
    overall_exploited_ratio = (
        _own_exploitation_count / _own_donation_count
        if _own_donation_count > 0 else 0.5
    )

    # Base threshold: increases with round but never exceeds 0.7
    base_threshold = 0.3 + 0.15 * (round_num / 50)
    base_threshold = min(base_threshold, 0.7)

    # Adjust threshold based on overall exploitation
    if overall_exploited_ratio > 0.4:
        threshold = base_threshold + 0.15  # stricter after being exploited often
    else:
        threshold = base_threshold

    # In late rounds, become more trusting to encourage cooperation
    if round_num > 80:
        threshold = max(threshold - 0.1, 0.2)

    # Hard cutoffs for extreme reputations
    if recipient_reputation > 0.9:
        return True
    if recipient_reputation < -0.5:
        return False

    return recipient_reputation > threshold
